                    print(f"      MajorRadius: {geom.MajorRadius}")
                if hasattr(geom, 'MinorRadius'):
                    print(f"      MinorRadius: {geom.MinorRadius}")
                if hasattr(geom, 'Position'):
                    print(f"      Position: {geom.Position}")

        # Check constraints
        if hasattr(obj, 'Constraints'):
            print(f"  Number of constraints: {len(obj.Constraints)}")
            for c in obj.Constraints:
                print(f"    Constraint: {c.Name if hasattr(c, 'Name') else 'unnamed'} - {c}")

FreeCAD.closeDocument(doc.Name)
